export const ALL_PROMPTS: Prompt[] = [
  { id: "P01", name: "The Flute Digger", genre: "italian-film", vibe: `Obscure 1960s Italian film score recording, heavy analog degradation and deep vinyl surface noise. Haunting solo flute melody in Dorian mode, sparse pizzicato strings, dry upright bass with no drums. Tempo around 68–76 BPM, slow and heavy. Cold, eerie atmosphere with unresolved tension — no catharsis, no chorus swell. Slight tape splice artifacts and wow-flutter. Sounds like a lost b-side no one has ever sampled. Loopable, cinematic dread, the kind of forgotten foreign record a serious crate digger would spend decades hunting in an overseas record shop.`, art: "/art/P01.jpg" },
  { id: "P02", name: "Cold Organ", genre: "dark-underground", vibe: `Early 1970s Eastern European modal jazz recording, warped tape and thick vinyl crackle throughout. Haunting Hammond organ lead in Phrygian mode, cold tremolo strings low in the mix, barely-audible upright bass. Tempo 70–78 BPM, heavy and deliberate. No drums, no vocals. Claustrophobic, dimly-lit atmosphere — sounds like it was recorded in a concrete building at 3am. Sparse and menacing with long sustained tones and silence used as texture. Designed to loop. The kind of obscure record that sounds dangerous when chopped and pitched.`, art: "/art/P02.jpg" },
  { id: "P03", name: "Psych Soul Ghost", genre: "dark-underground", vibe: `Late 1960s psychedelic soul recording, extreme tape degradation, heavy vinyl surface noise and random crackle pops. Sparse harpsichord in a diminished scale, dissonant tremolo strings, and faint ghostly wordless female vocal buried deep in the mix — not a lead, just a haunting texture. Dry upright bass, no drums. Tempo 63–72 BPM, dragging and hypnotic. Dark, hallucinatory mood — melancholy without resolution. Feels like a forgotten record pressed in small quantities that never got distributed. Loopable and deeply sampleable when pitched up.`, art: "/art/P03.jpg" },
  { id: "P04", name: "Middle East Menace", genre: "dark-underground", vibe: `Early 1970s Middle Eastern orchestral recording, analog tape saturation with heavy wow-flutter and vinyl degradation. Oud or sitar melody in a Hijaz scale, dark cello section low in the mix, minimal upright bass. No drums, no vocals. Tempo 72–80 BPM, swaying and hypnotic. Cinematic dread — the kind of music that plays before something terrible happens in a film. Unresolved harmonic tension throughout, no cathartic release. Sparse arrangement with long held tones and deep silences. Sounds like it was recorded in Cairo or Istanbul in 1971 and never released outside its region. Built to loop endlessly.`, art: "/art/P04.jpg" },
  { id: "P05", name: "Hybrid Bridge", genre: "boom-bap", vibe: `1970s rare soul recording, heavy analog tape saturation and vinyl crackle. Slow Rhodes piano melody in Dorian mode, sparse cold strings and minimal upright bass. No drums. Tempo 74–82 BPM. Single ghostly female vocal hum buried under the instruments — not a performance, just an atmosphere. Dark, contemplative mood with no harmonic resolution. Imperfect human timing and tape artifacts throughout. Lush enough to feel emotional, menacing enough to feel dangerous. Loopable, designed to be chopped, pitched, and flipped into something brutal.`, art: "/art/P05.jpg" },
  { id: "P06", name: "Black Church", genre: "soul-gospel", vibe: `Late 1960s Black church recording, warm analog tape saturation and subtle vinyl surface noise. Full Hammond B3 organ lead, thick gospel choir harmonies rising and falling in waves, strong live bass walking underneath. No drums except occasional hand claps buried deep in the mix. Tempo 72–82 BPM. Deep spiritual yearning — voices stacking on top of each other, call and response between organ and choir. Feels like it was recorded live in a small church on a Sunday morning. Raw, emotional, unrehearsed human feel. The kind of sacred music that becomes transcendent when chopped, pitched up, and placed underneath something hard.`, art: "/art/P06.jpg" },
  { id: "P07", name: "Late Night Jazz Session", genre: "jazz", vibe: `Early 1970s small ensemble jazz recording, dry room acoustics, analog tape hiss and subtle vinyl surface noise. Upright bass walking line as the anchor, brushed snare and ride cymbal swinging loosely, muted trumpet or tenor saxophone carrying the melody. Tempo 84–96 BPM, light and swinging but melancholic underneath. Imperfect human timing, musicians responding to each other in real time. Sounds like a late-night session pressed in small quantities for a regional label. The kind of warm, dusty live jazz record producers have been digging for, looping two bars, and building entire worlds around.`, art: "/art/P07.jpg" },
  { id: "P08", name: "Aching Soul Vocal", genre: "soul-gospel", vibe: `Mid 1970s dramatic soul recording, heavy analog tape saturation and deep vinyl crackle throughout. Wailing female lead vocal — emotive, strained, gospel-drenched — singing a slow aching minor key melody. Voice cracking and straining at the edges, raw and completely unrestrained. Lush string arrangement underneath, warm piano chords, live bass with no drums. Tempo 65–76 BPM, slow and weighted with grief. The kind of devastating soul performance built to be chopped into a two-bar loop, pitched up several semitones, and transformed into something completely unrecognizable but emotionally overwhelming.`, art: "/art/P08.jpg" },
  { id: "P09", name: "45 Flip Ready", genre: "chipmunk", vibe: `Upbeat early 1960s girl group soul recording, bright analog tape, light vinyl surface noise. Call and response female vocal harmonies over a lively minor key chord progression with a bouncy swing feel. Piano, rhythm guitar, walking bass, and a loose live drum groove. Crisp punchy horn stabs punctuating the vocal phrases. Tempo 108–120 BPM, energetic and driving. Feels like a regional 45 single that got local airplay but never crossed over nationally. Designed to be pitched up several semitones and transformed into a buoyant, chipmunked sample flip that still retains the original warmth and swing.`, art: "/art/P09.jpg" },
  { id: "P10", name: "The Break", genre: "drum-break", vibe: `1970s live funk drum performance recorded to analog tape with moderate vinyl surface noise. No melody, no harmony, no bass — a single drummer in an empty room. Structure in three acts: opens with a tight locked-in groove — deep punchy kick, cracking snare, syncopated hi-hats. Mid-section breaks into a full extended drum solo breakdown — the drummer cuts loose completely, trading between snare rolls, tom fills, open hi-hat splashes, rim shots, and rapid kick doubles for eight to sixteen bars. Final section snaps back to the locked groove, tighter and harder than before. Tempo 95–108 BPM with natural human rushing and dragging throughout.`, art: "/art/P10.jpg" },
  { id: "P11", name: "Library Cue", genre: "tv-score", vibe: `Early 1970s production library cue recording — functional broadcast music, analog tape, light vinyl degradation. Short self-contained piece with a deliberate mood arc: tense sparse introduction, slowly building middle section, unresolved hanging ending. Solo flute or vibraphone over cold sparse strings and a dry upright bass. No vocals, no drums. Tempo 76–88 BPM. Pressed in a quantity of 300 copies for broadcaster licensing, never heard outside a television studio. Deeply loopable, harmonically restless, completely undiscovered — the definition of untouched sample material sitting in a library crate.`, art: "/art/P11.jpg" },
  { id: "P12", name: "Tokyo Deep", genre: "japanese", vibe: `Late 1970s Japanese soul recording, warm analog tape with a slightly muffled, intimate room sound. Mid-tempo groove around 76–86 BPM. Soft muffled Rhodes keys carrying a gentle, dreamy minor key melody — delicate, slightly distant. Clean natural upright bass walking slowly underneath. Minimal brushed drums — sparse kick, quiet snare, hi-hat barely there. Bright distant female vocal singing a melancholic Japanese pop melody, reverb-soaked and floating above the mix. Subtle flute or vibraphone accents weaving between vocal phrases. The kind of obscure Japanese soul pressing from a small regional label never distributed outside Japan, loopable and deeply sampleable when pitched up and slowed.`, art: "/art/P12.jpg" },
  { id: "P13", name: "Cinemascope Nero", genre: "italian-film", vibe: `Early 1970s Italian crime film soundtrack recording, analog tape with a slightly hollow studio sound. Mid-tempo groove around 80–92 BPM. Funky wah-wah rhythm guitar chopping on the upbeats, deep walking electric bass with a slightly overdriven tone. Lead instrument alternating between a haunting solo flute and a tense tremolo string section — the two trading off, never resolving harmonic tension. Sparse Hammond organ stabs punctuating dramatic moments. No vocals. Slightly eerie, slightly funky. Pressed in small quantities for film distribution only, never commercially released.`, art: "/art/P13.jpg" },
  { id: "P14", name: "Midnight Sanctuary", genre: "soulful-house", vibe: `Early 1990s New York underground soulful house music recording, warm analog mixing board saturation. Four-on-the-floor kick drum at 122 BPM, crisp snare on the two and four, shimmering open hi-hat. Deep warm analog bass line in a gospel-influenced minor chord progression. Live gospel piano chords stabbing on the upbeats — full rich voicings with extended harmonies. A full-throated Black female lead vocal — powerful, church-trained, deeply emotional. Background choir harmonies swelling in call and response. Congas and shakers woven into the percussion bed. The feeling of a late-night underground club where the music is spiritual, not just physical.`, art: "/art/P14.jpg" },
  { id: "P15", name: "Filtered Gold", genre: "disco-house", vibe: `Late 1990s French-influenced disco house production, warm heavily filtered analog processing throughout. Four-on-the-floor kick at 124 BPM, tight punchy snare, closed hi-hats with occasional open hat flares. A deeply funky filtered bass line — the low-pass filter slowly sweeping open and closed over the eight bar cycle. Lush 1970s disco string section looped and filtered. Tight funky rhythm guitar chopping on the upbeats, wah-wah processing giving it a rubbery elastic feel. Brass stabs accenting off-beats. Single short vocal phrase chopped into a two bar loop, pitched and effected until it functions as an instrument. Designed to loop for eight minutes without losing momentum.`, art: "/art/P15.jpg" },
  { id: "P16", name: "Barrio Nocturno", genre: "latin", vibe: `Late 1960s New York Latin soul orchestral recording, warm analog tape with deep vinyl surface noise. Mid-tempo groove around 74–84 BPM. Dramatic dark string section playing a slow moody minor key melody with cinematic tension. Upright bass walking a deep slow groove, congas and timbales playing a restrained rhythmic pattern. Dark piano or organ chords voicing the harmony in the lower register. Female vocal texture floating above — not singing words, just wordless humming, reverb-soaked, almost ghostly. The feeling of a deserted Latin neighborhood at midnight. Pressed on a small New York indie label in 1969. The kind of orchestral Latin soul recording that loops and transforms into something devastating.`, art: "/art/P16.jpg" },
  { id: "P17", name: "Giallo Nero", genre: "italian-film", vibe: `Mid 1970s Italian horror film score recording, analog tape with a slightly hollow studio sound. A pulsing electric bass line locked into a hypnotic minor key ostinato, and above it a cold analog synthesizer playing a slow repeating arpeggio that spirals and refuses to resolve. Harpsichord interjecting sharp stabbing phrases between the synth lines. No drums except a slow plodding kick — one hit every two beats, deliberate and funeral. Distant tremolo strings swelling in and out like something breathing in a dark room. A ghostly whispering female voice buried deep in the reverb — not words, just a barely-audible tonal hum. Church organ drone underneath everything. Tempo 68–80 BPM. Pressed for Italian cinema distribution only.`, art: "/art/P17.jpg" },
  { id: "P18", name: "Murda Muzik Source", genre: "cinematic-dark", vibe: `Late 1960s dark orchestral recording, heavy analog tape degradation and deep vinyl surface noise throughout. A single repeating minor piano figure in harmonic minor — cold, mechanical, four to six notes cycling obsessively with no resolution. Not a melody, a motif. Sparse mournful string section underneath, violins playing long sustained tones in the lowest register, bowing slowly and without warmth. No drums, no bass. Tempo 68–80 BPM, slow and deliberate, heavy with dread. Occasional dissonant cello swell entering from silence and retreating back into it. Pressed on a small European label in 1967. Designed to be the foundation under the most menacing rap ever recorded.`, art: "/art/P18.jpg" },
  { id: "P19", name: "Late Night Broadcast", genre: "tv-score", vibe: `Early 1970s American television crime drama score cue, analog tape with a slightly dry studio sound. Three distinct sections that loop back naturally. Opening: tense and sparse — lone electric piano playing a short repeating minor key figure, upright bass walking slowly. Middle: the groove drops in — punchy wah-wah rhythm guitar, tight snare, walking bass, muted trumpet playing a short bluesy phrase. Final: everything strips back to just the electric piano motif. Tempo 82–96 BPM. The feeling of a surveillance scene — a detective watching someone from a car at 2am. Composed as functional background music for a gritty weekly crime drama, 1972.`, art: "/art/P19.jpg" },
  { id: "P20", name: "São Paulo Basement", genre: "brazilian", vibe: `Late 1970s Brazilian jazz-funk fusion recording from São Paulo, warm analog tape with a slightly humid room sound. Electric Rhodes piano carrying a bright hypnotic minor key melody with a distinctly Brazilian harmonic sensibility — the chord voicings more circular, more resolved into sadness than tension. Deep locked electric bass groove. Surdo and pandeiro percussion weaving through with congas. A breathy flute doubling the Rhodes melody in a higher register. Short wordless female vocal hum floating through the bridge sections. Tempo 88–100 BPM. Pressed on a small regional Brazilian label in 1978, never exported outside Brazil.`, art: "/art/P20.jpg" },
  { id: "P21", name: "Thunder Soul", genre: "boom-bap", vibe: `Early 1970s live high school stage band funk recording, raw and unpolished analog tape with natural room reverb. A large ensemble of teenage musicians playing with more feeling than technical precision — slightly imperfect intonation, tempos that breathe because the drummer is seventeen and full of adrenaline. Locked funky groove driven by a tight two-bar horn riff over a deep rhythm section. Mid-section: a young female flute soloist steps out over a stripped-back groove, the flute slightly breathy and raw. Then the drummer breaks into a full extended solo before the full ensemble crashes back in. Tempo 92–108 BPM. Recorded live in a high school gymnasium in 1972.`, art: "/art/P21.jpg" },
  { id: "P22", name: "Stadium Brass", genre: "marching-band", vibe: `Early 1970s college marching band live stadium recording, warm and slightly distorted from the outdoor field microphones, crowd noise audible. A massive brass section — sixty to eighty horns — performing a slow triumphant minor-to-major chord progression that swells and retreats like a tide. The horns begin sparse, just low brass laying foundation. Then the full section erupts. Mid-section: the brass drops to silence except for a single trumpet soloist playing a soaring gospel-influenced melodic phrase — raw, slightly sharp, deeply emotional. Then the full section crashes back at full volume. Percussion thundering underneath. Tempo 68–80 BPM. The kind of single horn stab that, isolated and filtered, becomes the foundation of a stadium rap anthem.`, art: "/art/P22.jpg" },
  { id: "P23", name: "Dark Cinematic Loop", genre: "cinematic-dark", vibe: `Late 1980s to early 1990s cinematic orchestral recording, slightly degraded analog tape with subtle warmth and soft vinyl texture. A haunting minimal piano melody in a natural minor scale — four to eight notes, simple and devastating. Long slow string pads sustaining behind the piano like a held breath — not dramatic swells, just patient presence. Deep resonant cello line moving in slow half notes underneath. No drums, no percussion. Tempo 65–80 BPM, slow and weighted. Silence used as much as sound. The emotional register is cinematic grief. Reverb on everything, long tails, sounds bleeding into each other. Designed to work equally well under introspective verses and euphoric drops.`, art: "/art/P23.jpg" },
  { id: "P24", name: "Warsaw Glass", genre: "polish-jazz", vibe: `Early 1970s Polish jazz recording from Warsaw, cold analog tape with metallic room reverb and moderate vinyl surface noise. Crystalline grand piano playing a slow repeating figure in D Dorian — cold, searching, each note ringing with brittle clarity. Upright bass recorded dry and forward, woody attack with minimal sustain. Harmon-muted trumpet entering from silence, playing a restrained melody that circles without resolving. Mid-section: the piano steps into an extended solo — spare, deliberate, sustain pedal catching overtones that shimmer and decay. Tempo 72–82 BPM. No vocals. The atmosphere of a concrete studio at midnight behind the Iron Curtain. Pressed on a state-owned label in a limited domestic run, never exported outside Eastern Europe. Designed to loop hypnotically — the kind of cold dusty record a producer would loop two bars of and build entire worlds around.`, art: "/art/P24.jpg" },
  { id: "P25", name: "Dead Sea Scroll", genre: "israeli-psych", vibe: `Early 1970s Israeli psychedelic folk recording from Tel Aviv, warm analog tape with heavy midrange saturation and deep vinyl crackle. A solo oud carrying an ornate melody in Hijaz scale — dark, ancient, each microtonal bend landing between the cracks of Western tuning. Bouzouki arpeggios shimmering underneath in a slow tremolo, metallic and bright. Electric guitar drenched in spring reverb playing sparse modal phrases that echo and decay. Mid-section: the oud steps into an extended solo passage — rapid ornamental runs climbing through the augmented second intervals, each phrase more desperate than the last before retreating to the central motif. Tempo 68–78 BPM, swaying and hypnotic. No vocals except a distant wordless hum buried in reverb. Pressed in a quantity of 300 on a small Tel Aviv indie label, never distributed outside Israel. Built to loop endlessly — the kind of forgotten Middle Eastern recording a crate digger would spend years hunting and flip into something devastating.`, art: "/art/P25.jpg" },
  { id: "P26", name: "Budapest Hammer", genre: "hungarian-psych", vibe: `Mid 1970s Hungarian psychedelic folk-rock recording, warm Eastern Bloc tape with moderate vinyl surface noise. A cimbalom playing a repeating figure in Hungarian minor — hammered strings shimmering with complex overtones, each strike percussive and bell-like with long metallic decay. Tárogató entering with a dark reedy melody, mournful and almost vocal in its phrasing. Electric guitar underneath playing slow fuzz-drenched drones through a phaser. Mid-section: the cimbalom breaks into an extended solo — rapid hammered runs climbing through augmented second intervals of Hungarian minor, restless and searching. Tempo 74–84 BPM. No vocals. Pressed in a limited domestic run, never exported beyond the Eastern Bloc. Loopable — the kind of obscure Eastern European record that sounds like nothing else when chopped and pitched.`, art: "/art/P26.jpg" },
  { id: "P27", name: "Autobahn Noir", genre: "krautrock", vibe: `Early 1970s German experimental recording, warm precision-engineered tape with dense midrange and faint vinyl hiss. A Moog synthesizer locked into a slow hypnotic filter sweep — low-pass cutoff opening and closing over an eight-bar cycle, dark and vast. Farfisa organ sustaining a cold Phrygian drone through heavy spring reverb, swirling and disorienting. Electric guitar playing a single repeating note through a ring modulator, metallic and alien. Mid-section: the Moog steps into an extended passage — filter fully open, revealing a complex evolving timbre that spirals upward before retreating beneath the cutoff. Tempo 82–92 BPM, relentless and motorik. No vocals. Endless night highway through industrial Germany. Pressed on a small independent label in a run of 500 copies. Designed to loop indefinitely — the kind of cold kosmische record a producer would slow down and build their most hypnotic record around.`, art: "/art/P27.jpg" },
  { id: "P28", name: "Anatolian Dust", genre: "turkish-psych", vibe: `Early 1970s Turkish psychedelic recording from Istanbul, saturated analog tape with heavy compression and thick vinyl surface noise. An amplified bağlama locked into a rapid tremolo melody in Hicaz makam — buzzing, metallic, microtonal intervals landing where Western scales cannot reach. Farfisa organ sustaining dark modal chords underneath, thin and sinister. Electric bass played high on the neck following the melodic contour, overdriven and woolly. Mid-section: the bağlama steps into an extended solo — tremolo intensifying, ornamental hammer-ons climbing through augmented seconds of Hicaz, raw and furious. Tempo 70–80 BPM, heavy and swaying. No vocals. Mono mix, dense and punchy. Pressed as a 45 RPM single on a small Turkish label, 500 copies, never distributed outside Anatolia. Built to loop endlessly — the kind of forgotten Turkish record a crate digger would spend decades hunting in an overseas record shop.`, art: "/art/P28.jpg" },
  { id: "P29", name: "Addis Midnight", genre: "ethio-jazz", vibe: `Early 1970s Ethiopian recording from Addis Ababa, dry close-miked analog tape with minimal reverb and moderate vinyl degradation. Hammond organ carrying an ornate melody in ambassel mode — dark, aching, notes orbiting a tonal center without resolving, each phrase heavy with spiritual longing. Tenor saxophone entering with a raw solo, following Ethiopian melodic contours with heavy vibrato and ornamental turns. Upright bass playing a deep repetitive pattern underneath. Mid-section: the organ steps into an extended passage — expression pedal swelling, melody climbing into the upper register with increasing urgency before cycling back. Tempo 72–82 BPM. No vocals. The atmosphere of a dimly-lit Addis Ababa nightclub in 1973. Pressed on a small Ethiopian label, 500 copies, never exported. Loopable and hypnotic — the kind of forgotten African recording a producer would loop two bars of and build something timeless around.`, art: "/art/P29.jpg" },
  { id: "P30", name: "Accra Gold", genre: "ghana-funk", vibe: `Mid 1970s Ghanaian highlife funk recording from Accra, warm analog tape with bright midrange and moderate vinyl surface noise. Clean-toned electric guitar locked into a shimmering two-bar ostinato in natural minor — bright, percussive, each picked note cutting through the mix. Second guitar playing a rhythmic comping figure with rolling highlife swing. Electric bass walking a melodic counter-line, round and deep. Congas and cowbell weaving a polyrhythmic pattern. Mid-section: the lead guitar breaks into an extended solo — pentatonic minor runs with chromatic passing tones, the picking attack ahead of the beat creating a forward pull. Tempo 92–104 BPM. No vocals. The atmosphere of a packed Accra dance hall in 1975. Pressed on a small Ghanaian label, limited domestic run, surviving copies showing decades of heavy play. Designed to loop — the kind of dusty West African record a producer would pitch down and flip into something that knocks.`, art: "/art/P30.jpg" },
  { id: "P31", name: "Bombay Reel", genre: "bollywood", vibe: `Early 1970s Bollywood film score recording from Bombay, warm analog tape with a slightly compressed studio sound and moderate vinyl surface noise. A solo sitar carrying a slow ornate melody in a raga-influenced minor scale — each note bent and sustained with microtonal precision. Lush tremolo string section swelling underneath, tablas weaving a restrained rhythmic pattern, and a distant female vocal humming a wordless melody drenched in reverb. Hammond organ sustaining dark chords in the lower register. Mid-section: the sitar steps into an extended solo passage — rapid ornamental runs climbing through the scale before retreating to the central motif. Tempo 72–82 BPM, hypnotic and swaying. The atmosphere of a dramatic scene in a film that played in Bombay cinemas and nowhere else. Pressed for Indian domestic distribution only, never exported. Loopable and devastating — the kind of forgotten Bollywood score cue a global crate digger would build entire projects around.`, art: "/art/P31.jpg" },
  { id: "P32", name: "Paris Noir", genre: "french-library", vibe: `Early 1970s French orchestral recording from a Parisian studio, warm analog tape with subtle room reverb and light vinyl surface noise. A harpsichord playing a slow repeating baroque-influenced figure in harmonic minor — precise, cold, each note sharp and deliberate. Lush string section underneath sustaining dark cinematic chords. Solo flute entering with a breathy melody floating above the arrangement, melancholic and detached. Nylon-string guitar comping sparse voicings in the background. Mid-section: the flute steps into an extended solo — the melody climbing through chromatic passing tones with French classical phrasing before retreating to the opening theme. Tempo 74–84 BPM. No vocals. The atmosphere of a rain-soaked Paris crime film. Pressed as a library music cue for French broadcast use, 200 copies, never commercially released. Designed to loop — the kind of elegant forgotten European recording a producer would pitch down and build something cinematic around.`, art: "/art/P32.jpg" },
  { id: "P33", name: "Sigma Gold", genre: "philly-soul", vibe: `Mid 1970s Philadelphia soul orchestral recording, warm analog tape saturated with the signature sound of a legendary Philly recording studio. A massive string section — thirty players — sweeping through a dramatic minor-key arrangement that swells and retreats in emotional waves. Rhodes electric piano underneath playing rich extended chord voicings, live electric bass locked into a slow groove. Full horn section — trumpet, trombone, tenor saxophone — playing arranged stabs between the string phrases. Mid-section: the strings drop to silence and a solo flugelhorn plays an exposed melodic phrase — warm, golden, deeply emotional — before the full orchestra crashes back in. Tempo 76–86 BPM. No vocals. The kind of orchestral soul recording pressed on a Philadelphia independent label in 1975, the B-side that got overlooked. Built to be chopped — a single string swell from this record becomes the foundation of an anthem.`, art: "/art/P33.jpg" },
  { id: "P34", name: "Shaft Alley", genre: "blaxploitation", vibe: `Early 1970s American blaxploitation film score recording, analog tape with a slightly gritty studio sound and moderate vinyl surface noise. A wah-wah rhythm guitar chopping a tight syncopated pattern over a deep walking electric bass with a slightly overdriven tone. Harmon-muted trumpet playing a cool minor-key melody — bluesy, understated, urban. Sparse string section sustaining tension underneath. Hammond B3 organ comping dark chords in the background. Mid-section: the trumpet steps into an extended solo — breathy, bending notes at the edges, the melody circling through Dorian intervals with late-night city cool. Tempo 82–92 BPM. No vocals. The atmosphere of a car chase through a city at midnight in 1973. Composed as a score cue for a crime film that was released regionally and forgotten. Loopable and funky — the kind of gritty urban score a producer would isolate the wah guitar from and flip into something dangerous.`, art: "/art/P34.jpg" },
  { id: "P35", name: "Astral Temple", genre: "spiritual-jazz", vibe: `Early 1970s spiritual jazz recording, warm analog tape with reverberant studio sound and subtle vinyl surface noise. Rhodes electric piano carrying a slow modal drone in D Dorian — warm, cosmic, each chord sustained with tremolo and allowed to decay naturally. Solo flute floating above playing a meditative melody that circles without resolving. Upright bass holding sparse root notes, deep and resonant. Congas and finger cymbals weaving a gentle polyrhythmic texture. Mid-section: the Rhodes steps into an extended passage — chords opening into wider voicings, tremolo intensifying, the sound becoming more spacious and devotional before cycling back. Tempo 68–78 BPM. No vocals. Pressed in a quantity of 300 on a small independent jazz label, never reissued. The kind of cosmic jazz record a producer would loop two bars of and build entire worlds around.`, art: "/art/P35.jpg" },
  { id: "P36", name: "Chrome Love", genre: "synth-funk", vibe: `Early 1980s American synth-funk recording, warm analog synthesizer pads with a polished studio sheen and subtle tape compression. A Prophet synthesizer playing lush extended minor chord voicings — rich, shimmering, each pad slowly evolving through filter sweeps. Moog bass synthesizer underneath locked into a deep repetitive pattern. Fender Rhodes electric piano adding sparse melodic phrases between the synth pads. Talk box vocal texture floating through the bridge — not words, just a vocoded human tone, robotic yet emotional. Mid-section: the Prophet steps into an extended passage — the filter fully open, arpeggiated chords cascading in a slow minor-key sequence before retreating beneath the bass. Tempo 78–88 BPM. The atmosphere of a late-night quiet storm radio broadcast in 1983. Pressed on a small independent funk label, limited regional distribution. The kind of polished synth-soul record a producer would slow down, loop the pad, and build something heavy underneath.`, art: "/art/P36.jpg" },
  { id: "P37", name: "Temple Fist", genre: "kung-fu-score", vibe: `Mid 1970s Hong Kong martial arts film score recording, analog tape with compressed studio sound and moderate vinyl degradation. Solo erhu carrying a slow pentatonic minor melody — dark, tense, each bowed note sustaining with a nasal human-voice quality. Woodblocks, gongs, and small cymbals punctuating dramatic moments with sharp accents. Tremolo strings sustaining in low dissonant clusters. Guzheng plucking sparse arpeggiated figures between the erhu phrases. Mid-section: the erhu steps into an extended passage — melody climbing rapidly through the pentatonic scale, bowing intensifying, before dropping to silence and a single gong strike. Tempo 70–80 BPM. No vocals. Pressed for Asian cinema distribution only, never released outside the region. Built to loop — the kind of forgotten Eastern film score a producer would pitch down and build their most cinematic record around.`, art: "/art/P37.jpg" },
  { id: "P38", name: "Aegean Ghost", genre: "greek-rebetiko", vibe: `Early 1970s Greek laiko recording from Athens, warm analog tape with heavy midrange saturation and deep vinyl crackle. A solo bouzouki carrying a rapid tremolo melody in a Phrygian-influenced mode — bright, metallic, each picked note ringing with a Mediterranean intensity. Nylon-string guitar comping dark minor chords underneath in a slow rhythmic pattern. Electric bass following the melodic contour, warm and round. Sparse string section sustaining long tones in the background. Mid-section: the bouzouki breaks into an extended solo — rapid descending runs through the Phrygian intervals, each phrase more urgent than the last before retreating to the central riff. Tempo 72–82 BPM, swaying and hypnotic. No vocals. The atmosphere of a smoky Athens nightclub in 1972. Pressed on a small Greek label, limited domestic run, never distributed outside the Mediterranean. Loopable — the kind of forgotten Greek recording a crate digger would spend years hunting and flip into something haunting.`, art: "/art/P38.jpg" },
  { id: "P39", name: "Shadow Temple", genre: "8-bit", vibe: `Late 1980s 8-bit console game soundtrack, sparse square wave synthesis with limited polyphony. A single pulse wave carrying a slow haunting melody in E Phrygian — each note isolated by digital silence, the flat-second interval creating deep unease. Triangle wave bass holding long sustained drone notes, hollow and cavernous. Second pulse wave entering with a high-register tremolo pulsing like something breathing in a dark corridor. Mid-section: the lead melody plays alone, descending through the Phrygian scale before the drone returns. Tempo 68–78 BPM. Pure 8-bit synthesis through a low-resolution DAC, aliasing and bit-crushing artifacts intact, no reverb, no warmth. Composed for a cartridge RPG pressed in a small run for the Japanese domestic market, never localized. A four-bar phrase that cycles without resolution — the kind of eerie 8-bit composition a producer would sample raw and build their most atmospheric record around.`, art: "/art/P39.jpg" },
  { id: "P40", name: "Tiny Ghost", genre: "childrens-toy", vibe: `Early 1970s budget children’s music recording, thin vinyl pressing with heavy surface noise and boxy mono room sound. Toy piano carrying a slow melody in A minor pentatonic — tinny, detuned, percussive with no sustain. Glockenspiel doubling the melody an octave higher, bright and metallic. Recorder entering with a breathy sustained tone underneath. Music box mechanism pulsing a two-note ostinato — plucked-comb tone cold and mechanical. Mid-section: the toy piano plays alone, completely exposed — a four-note descending figure repeating with the patience of a lullaby that never resolves. Tempo 66–76 BPM, slow and deliberate. No vocals. Pressed on thin vinyl for a small educational distributor, sold at school book fairs, never commercially distributed. Designed to loop — the kind of forgotten children’s record that becomes haunting when pitched down and placed underneath something hard.`, art: "/art/P40.jpg" },
  { id: "P41", name: "Lusaka Fuzz", genre: "zamrock", vibe: `Mid 1970s Zambian psychedelic rock recording from Lusaka, warm analog tape with heavy saturation and deep vinyl surface noise. Fuzz-drenched electric guitar carrying a slow hypnotic melody in D Dorian — distortion ragged and unpredictable, created by a damaged amplifier circuit. Upright bass playing a circular melodic pattern rooted in indigenous Zambian folk intervals. Farfisa combo organ sustaining dark chords, detuned and buzzing. Mid-section: the fuzz guitar steps into an extended solo — pentatonic runs with unexpected interval leaps drawn from Zambian tonal language, wah-wah pedal sweeping slowly. Tempo 78–88 BPM. No vocals. The atmosphere of a concrete rehearsal space in the Copperbelt in 1975. Pressed on a small Lusaka label, 500 copies, never exported. Designed to loop — the kind of impossibly rare African psych record a crate digger would build entire projects around.`, art: "/art/P41.jpg" },
  { id: "P42", name: "Kinshasa Gold", genre: "congolese-rumba", vibe: `Early 1970s Congolese rumba recording from Kinshasa, warm analog tape with moderate hiss and reflective room sound. Clean-toned electric guitar playing rapid fingerpicked arpeggios in natural minor — bright, liquid, cascading like water over stones, each note bell-like. Second guitar playing a rhythmic comping pattern that interlocks with the lead. Deep electric bass walking a melodic counter-line, round and boomy. Congas and maracas weaving a buoyant polyrhythmic bed. Mid-section: the lead guitar launches into a sebene passage — rapid-fire melodic runs climbing through minor pentatonic, virtuosic and hypnotic. Tempo 86–96 BPM. No vocals. Pressed on a small Kinshasa label, 1,000 copies, never distributed outside Central Africa. Built to loop — the kind of forgotten Congolese guitar record a producer would pitch down and flip into something no one has ever heard.`, art: "/art/P42.jpg" },
  { id: "P43", name: "Medellín Fuzz", genre: "colombian-cumbia", vibe: `Early 1970s Colombian psychedelic cumbia recording from a Medellín studio, hot analog tape with heavy saturation and a boxy room sound. A fuzz electric guitar carrying a slow gaita-derived melody in harmonic minor — buzzy, trebly, the distortion raw and garage-like. Farfisa combo organ underneath sustaining nasal reedy chords. Deep electric bass locked into a simple two-bar repetitive pattern. Congas providing the core rhythmic pulse, guacharaca scraping a steady shuffle pattern, timbales accenting transitions. Mid-section: the fuzz guitar steps into an extended solo — the gaita-influenced phrasing climbing through Phrygian-adjacent intervals with flat-second tension before cycling back to the central riff. Tempo 78–88 BPM. No vocals. Pressed on a small Colombian coastal label for jukebox distribution, never exported. Designed to loop — the kind of forgotten Colombian fuzz-cumbia record a producer would pitch down and flip into something hypnotic and menacing.`, art: "/art/P43.jpg" },
  { id: "P44", name: "Lima Tremolo", genre: "peruvian-chicha", vibe: `Mid 1970s Peruvian chicha recording from a small Lima studio, lo-fi analog tape with heavy saturation and dead intimate room sound. Clean electric guitar drenched in spring reverb and tremolo playing a slow Andean pentatonic minor melody — wet, shimmering, each note wobbling, deeply melancholic. Farfisa combo organ doubling the melody with a thin nasal tone. Electric bass holding a repetitive cumbia-derived pattern underneath. Congas and guiro providing a steady rhythmic bed. Mid-section: the guitar steps into an extended solo — tremolo intensifying, pentatonic phrases climbing with the aching nostalgia of Andean folk melody through cheap amplification. Tempo 78–88 BPM. No vocals. Pressed in a quantity of 300 on a tiny Lima label, never left Peru. Built to loop — the kind of forgotten Peruvian chicha recording a producer would pitch down and flip into something devastating and ancient-sounding.`, art: "/art/P44.jpg" },
  { id: "P45", name: "Bangkok Ghost", genre: "thai-psych", vibe: `Late 1960s Bangkok psychedelic luk thung recording, warm analog tape with midrange-heavy EQ and moderate vinyl surface noise. Overdriven fuzz guitar playing ornamental Thai pentatonic figures with pitch slides — melodic phrasing derived from traditional patterns pushed through a damaged tube amplifier. Thin reedy Farfisa combo organ carrying sustained modal chords. Hammered dulcimer interjecting bright metallic accents between the guitar phrases. Two-stringed bowed fiddle buried in the mix, almost vocal in quality. Mid-section: the fuzz guitar steps into an extended solo — rapid ornamental slides climbing through Thai pentatonic with chromatic passing tones. Tempo 76–86 BPM. No vocals. Mono recording from a small Bangkok studio, pressed as a 7-inch single, a few hundred copies, most destroyed by tropical climate. The kind of impossibly rare Southeast Asian recording a crate digger would build something no one has ever heard around.`, art: "/art/P45.jpg" },
  { id: "P46", name: "Phnom Penh Sunrise", genre: "cambodian-rock", vibe: `Early 1970s Cambodian rock recording from Phnom Penh, analog tape with heavy hiss and bright midrange-forward mono room sound. Spring-reverb-drenched tremolo guitar playing a slow Khmer pentatonic melody — bright, cutting, surf-influenced technique applied to Southeast Asian modal phrasing with flattened second intervals. Thin reedy combo organ sustaining dark minor chords. Congas and bongos weaving a Latin-influenced rhythmic pattern. Mid-section: the guitar steps into an extended passage — tremolo intensifying, melody descending through Phrygian-adjacent intervals, each phrase carrying the weight of a culture on the edge of destruction. Tempo 72–82 BPM. No vocals. One of fewer than 200 surviving copies pressed in Phnom Penh before the music scene was erased. Built to loop — the kind of devastatingly rare recording recovered from a hidden cassette and given a second life as the foundation of something powerful.`, art: "/art/P46.jpg" },
  { id: "P47", name: "Moscow Midnight", genre: "soviet-estrada", vibe: `Late 1970s Soviet jazz-funk recording from a Moscow state studio, warm ORWO analog tape with dense midrange and moderate vinyl surface noise. Soviet-made electric piano carrying a slow modal melody in D Dorian — thinner and more nasal than a genuine Rhodes, each chord brittle with unfamiliar harmonic character. Flugelhorn entering with a dark melodic phrase, played with conservatory precision over forbidden funk harmony. Full state orchestra string section sustaining lush minor chords. Upright bass walking a deliberate groove with flat-wound strings. Mid-section: the flugelhorn steps into an extended solo — impeccable runs through Dorian and Phrygian modes, classical training audible in every phrase. Tempo 78–88 BPM. No vocals. Pressed on the Melodiya state label in a limited domestic run, never exported outside the Soviet Union. The kind of hidden Iron Curtain recording a crate digger would flip into something the world has never heard.`, art: "/art/P47.jpg" },
  { id: "P48", name: "Belgrade Brass", genre: "yugoslav-funk", vibe: `Mid 1970s Yugoslav prog-funk recording from Belgrade, raw analog tape with live energetic room sound and moderate vinyl surface noise. Fender Rhodes electric piano playing a tight rhythmic figure in 7/8 time — the asymmetric meter feeling natural and instinctive. Wah-wah electric guitar chopping syncopated accents against the odd meter. Electric bass locked into a deep Balkan-influenced groove with chromatic passing tones from Romani tradition. Analog Moog synthesizer sustaining dark pads underneath. Mid-section: the Rhodes drops out and the guitar steps into an extended solo — Phrygian dominant runs with augmented second intervals of Balkan folk harmony, raw and intense. Tempo 82–92 BPM. No vocals. Pressed on a Yugoslav label for domestic distribution, never exported to the West. The kind of Eastern Bloc recording that sounds like nothing else when chopped and looped.`, art: "/art/P48.jpg" },
  { id: "P49", name: "Seoul Banned", genre: "korean-psych", vibe: `Early 1970s Korean psychedelic rock recording from Seoul, compressed analog tape with heavy fuzz saturation and a raw urgent room sound. A fuzz guitar carrying a slow descending melody in Korean pentatonic minor — each note bent with microtonal inflections from traditional pansori singing tradition, the distortion ragged from an overdriven Korean amplifier. A gayageum twelve-string zither interjecting bright plucked accents between the guitar phrases. Daegeum bamboo flute entering with a breathy haunting counter-melody. Farfisa organ sustaining dark minor chords underneath. Mid-section: the fuzz guitar steps into an extended solo — descending pentatonic phrases heavy with han, the uniquely Korean quality of deep unresolved sorrow. Tempo 72–82 BPM. No vocals. Pressed on a small Seoul label before the government banned and confiscated rock recordings, most copies destroyed. The kind of banned and burned Korean psych record that a crate digger would spend a lifetime searching for.`, art: "/art/P49.jpg" },
  { id: "P50", name: "Tokyo Underground", genre: "japanese-jazz-funk", vibe: `Mid 1970s Japanese jazz-funk recording from a prestigious Tokyo studio, pristine analog tape with virtually silent vinyl surface. Warm Fender Rhodes electric piano carrying a sophisticated melody in E Dorian with extended chord voicings — ninths and elevenths, each chord shimmering with subtle chorus. Deep upright bass with full low-end presence. Breathy tenor saxophone entering with a lyrical solo, warm tone with gentle vibrato. Flute doubling the Rhodes melody in a higher register, airy and intimate. Mid-section: the Rhodes steps into an extended passage — voicings opening wider, tritone substitutions and modal interchange creating bittersweet harmonic complexity. Tempo 78–88 BPM. No vocals. Audiophile-quality recording with wide stereo imaging. Pressed on a domestic-only Japanese jazz label, 1,000 copies, never exported. The kind of pristine Japanese jazz-funk record a producer would loop two bars of and build entire worlds around.`, art: "/art/P50.jpg" },
  { id: "P51", name: "Oran Cassette", genre: "algerian-rai", vibe: `Late 1970s Algerian raï recording from Oran, cassette-saturated analog tape with heavy compression and a lo-fi mono room sound. A gasba bamboo flute carrying an ornate melody in Hijaz scale — breathy, microtonal, each note bent with North African inflections that Western instruments cannot replicate. A cheap Farfisa keyboard sustaining dark minor chords underneath with a thin buzzy tone. Darbuka providing sharp rhythmic accents, guellal frame drum adding a deeper pulse. Mandole strumming a repetitive minor chord pattern. Mid-section: the gasba flute steps into an extended solo — rapid ornamental runs climbing through the augmented second intervals of Hijaz, raw and urgent. Tempo 82–92 BPM. No vocals. The atmosphere of a late-night recording session in an Oran backroom in 1978. Distributed only on cassette tape in Algerian market stalls, never pressed to vinyl, never exported. The kind of lost North African recording a global crate digger would build something devastating around.`, art: "/art/P51.jpg" },
  { id: "P52", name: "Marrakech Trance", genre: "moroccan-gnawa", vibe: `Mid 1970s Moroccan Gnawa trance-fusion recording, warm analog tape with natural room ambience from a riad courtyard. Sintir three-stringed bass lute carrying a deep hypnotic ostinato in Phrygian mode — woody, buzzing, each plucked note resonating with low-end depth. Krakeb iron castanets interlocking in a heavy metallic polyrhythmic pattern. Tenor saxophone entering with a dark modal melody over the trance groove. Tbel barrel drum providing a steady ceremonial pulse. Mid-section: the sintir locks into a two-bar figure and the saxophone steps into an extended solo — Phrygian runs spiraling upward with increasing spiritual intensity before cycling back. Tempo 80–90 BPM. No vocals. Pressed in a limited run for domestic Moroccan distribution only. Built to loop endlessly by spiritual design — the kind of hypnotic Gnawa recording a producer would low-pass filter and build their most atmospheric record around.`, art: "/art/P52.jpg" },
  { id: "P53", name: "Port-au-Prince Ceremony", genre: "haitian-vodou", vibe: `Late 1960s Haitian vodou-jazz recording from Port-au-Prince, warm analog tape with humid tropical room sound and subtle vinyl surface noise. Diatonic button accordion carrying a slow haunting melody in natural minor — reedy, wheezy, bellows audible in the recording. Tanbou ceremonial drum providing sacred rhythmic patterns. Vaksin bamboo trumpets blasting deep polytonal tones, multiple vaksin creating a dissonant brass choir unlike anything in Western music. Tcha-tcha shaker weaving a steady rhythmic bed. Mid-section: the accordion steps into an extended passage — melody climbing through Dorian intervals, bellows pumping harder, tone growing more urgent and spiritual. Tempo 76–86 BPM. No vocals. Pressed on a tiny Haitian label, never exported. The kind of forgotten Caribbean recording a producer would chop and build something sacred and devastating around.`, art: "/art/P53.jpg" },
  { id: "P54", name: "Tehran Ghost", genre: "iranian-psych", vibe: `Early 1970s Tehran psychedelic pop recording, analog tape saturation with heavy vinyl surface noise. Hammered santur carrying a cascading minor modal melody with quarter-tone inflections — bright metallic attack, seventy-two strings shimmering with overtones. Fuzz electric guitar doubling the melody an octave below, buzzing and dark. Weeping kamancheh spike fiddle entering with a nasal almost-human solo, wide vibrato bending through microtonal intervals between Western semitones. Farfisa organ sustaining dark chords underneath. Mid-section: the kamancheh steps into an extended solo — ornamental phrases spiraling around the tonal center without resolving, the bow drawing out pure melancholy. Tempo 74–84 BPM. No vocals. Pressed on a small Tehran label in 1973, most copies destroyed after the revolution. The kind of destroyed pressing a crate digger would spend a lifetime searching for in diaspora collections. Loopable and devastating.`, art: "/art/P54.jpg" },
  { id: "P55", name: "Kabul Rubab", genre: "afghan-folk", vibe: `Early 1970s Kabul recording from the Radio Afghanistan studios, mono tape with heavy hiss and close boxy room sound. Solo rubab playing a slow ornamental folk melody in Pashtun minor mode — three gut melody strings producing a deep buzzing attack while fifteen sympathetic strings shimmer and resonate with every note. Hand-pumped harmonium entering with sustained minor chords, bellows audible, equal-temperament tuning creating microtonal friction against the rubab’s intonation. Tabla providing a slow asymmetric rhythmic pattern. Mid-section: the rubab steps into an extended solo — rapid zamzama tremolo picking, sympathetic strings ringing in cascading overtones. Tempo 74–84 BPM. No vocals. Recorded for radio broadcast, never commercially pressed. Designed to loop. The kind of recording that survived three wars in a Kabul basement — the last evidence of a music scene erased from the Earth.`, art: "/art/P55.jpg" },
  { id: "P56", name: "Soweto Whistle", genre: "south-african-jazz", vibe: `Early 1970s South African township jazz recording from Johannesburg, warm analog tape with harsh mid-range and moderate vinyl surface noise. Penny whistle carrying a bright virtuosic melody in minor pentatonic — cutting, sharp, each note precise with rapid ornamental runs. Marabi piano playing a cyclical three-chord vamp, the pattern repeating hypnotically every two bars. Township jazz guitar adding a clean fingerpicked figure influenced by mbira patterns, bell-like and circular. Deep mbaqanga bass guitar walking a melodic counter-line. Mid-section: the penny whistle breaks into an extended solo — rapid pentatonic runs climbing with township shuffle swing. Tempo 84–94 BPM. No vocals. Pressed on a Johannesburg label, never exported outside southern Africa. Designed to loop — the kind of township jazz record a producer would loop the marabi vamp and build something that knocks.`, art: "/art/P56.jpg" },
  { id: "P57", name: "Havana Descarga", genre: "afro-cuban", vibe: `Late 1950s Afro-Cuban jazz descarga recording from Havana, warm analog tape with thin room sound and moderate vinyl surface noise. Piano playing a syncopated montuno figure in D minor — percussive, locked to the clave, cycling every two bars with rich voicings. Tres guitar interlocking a bright arpeggiated guajeo pattern, bell-like and repetitive. Tumbao upright bass anticipating the downbeat with deep woody tone. Congas playing an open-tone tumbao pattern, timbales cascading. Charanga wooden flute entering with rapid ornamental runs above the groove. Mid-section: the flute steps into an extended solo — virtuosic flights through minor pentatonic, breathy and raw. Tempo 88–98 BPM. No vocals. Pressed on a small pre-revolution Havana label, most copies never left Cuba. Designed to loop — the kind of forgotten descarga recording a producer would build an entire world around two bars of Cuban piano.`, art: "/art/P57.jpg" },
  { id: "P58", name: "Sunset Strip", genre: "g-funk", vibe: `Mid 1970s Ohio funk recording, warm 2-inch analog tape with natural room ambience from a Dayton studio session. A Minimoog synthesizer carrying a high-register sliding melody in G Dorian — portamento gliding between notes, bright sawtooth wave with resonant filter, the whining tone that defined an entire era of funk. Deep Moog bass underneath locked into a one-chord vamp, fat sine-wave blooming through a slow filter envelope. Hohner Clavinet D6 through Mutron envelope filter chopping funky upbeat accents. Wah-wah rhythm guitar scratching syncopated figures. Tight horn section — trumpet and tenor saxophone — punching short stabs between the Moog phrases. Tempo 100–110 BPM. No vocals. Tape saturation and Neve warmth on every element. Pressed on a small Dayton independent funk label in 1976, 500 copies, never distributed outside Ohio. The kind of raw Midwest funk record a West Coast producer would replay note-for-note and build an empire around.`, art: "/art/P58.jpg" },
  { id: "P59", name: "Detroit Mothership", genre: "p-funk", vibe: `Mid 1970s Detroit funk recording, warm 2-inch analog tape with natural room ambience and instrument bleed. A Minimoog synthesizer bass carrying a hypnotic one-chord vamp in E Dorian — fat sawtooth wave with slow filter bloom, each note opening from dark to warm. Hohner Clavinet D6 through a Mutron envelope filter chopping rhythmic upbeat accents, percussive and elastic. Wah-wah rhythm guitar adding syncopated scratches. Tight horn section — trumpet, trombone, tenor saxophone — punching short unison stabs. Mid-section: the Moog bass drops to a pedal tone and the horn section steps into a four-bar arranged passage. Tempo 98–108 BPM. No vocals. Neve console warmth, tape saturation on every element. Pressed on a small Midwestern label in 1976, 500 copies. The kind of deep funk record a Midwest crate digger would find in a Dayton thrift store and build an entire career around.`, art: "/art/P59.jpg" },
  { id: "P60", name: "Dungeon Smoke", genre: "atl-dungeon", vibe: `Early 1970s Southern psychedelic soul recording, warm analog tape with heavy saturation and a slightly humid room sound. A wah-wah rhythm guitar chopping slow syncopated figures through a Cry Baby pedal over a deep Moog synthesizer bass holding sustained minor chord tones. Hammond B3 organ with Leslie speaker running hot — slightly distorted, gospel-influenced voicings swelling and retreating. Congas and shakers weaving a loose polyrhythmic pattern. Solo flute entering with a breathy modal melody floating above, psychedelic and searching. Mid-section: the organ swells to full volume and the wah guitar drops to silence, leaving organ and flute in a moment of pure spiritual intensity. Tempo 78–88 BPM. No vocals. Pressed on a small Southern independent label in 1973, the kind of psychedelic soul that bridges church and acid. The kind of forgotten Southern funk a visionary Atlanta producer would replay live in a basement and build a double album around.`, art: "/art/P60.jpg" },
  { id: "P61", name: "Gulf Coast Player", genre: "houston-funk", vibe: `Early 1970s cinematic soul soundtrack recording, warm analog tape with lush orchestral presence and moderate vinyl surface noise. A sweeping string section playing a slow dramatic minor-key arrangement — violins and cellos sustaining long tones that swell with cinematic tension. Wah-wah rhythm guitar underneath chopping a syncopated funk pattern. Deep upright bass walking a slow deliberate groove. Rhodes electric piano voicing dark extended chords. Solo flugelhorn entering with a bluesy melodic phrase — warm, golden, slightly behind the beat. Mid-section: the strings drop and the flugelhorn plays alone over the walking bass — exposed, unhurried, heavy with Southern blues weight. Tempo 82–92 BPM. No vocals. Composed for a regional crime film soundtrack, pressed in small quantities, never commercially released outside the Gulf Coast. The kind of cinematic soul record a Houston producer would slow down, pitch into the basement, and let ride until the car vibrates.`, art: "/art/P61.jpg" },
  { id: "P62", name: "Memphis Cassette", genre: "memphis-dark", vibe: `Mid 1970s European horror film score recording, cold analog tape with a hollow studio sound and faint vinyl degradation. A minimal analog synthesizer playing a slow repeating four-note ostinato in B-flat Phrygian — cold, mechanical, each note precise and emotionless like a clock counting down. Dark pipe organ drone sustaining a tritone underneath, dissonant and funereal. Celesta entering with a high delicate descending figure — music-box tone, childlike and deeply unsettling. Tremolo strings swelling in the background, low and sustained, breathing like something in a dark room. Mid-section: the synthesizer ostinato plays alone — stripped bare, the Phrygian flat-second creating maximum dread in the silence between notes. Tempo 68–78 BPM. No vocals. Composed for an Italian horror film, pressed for European cinema distribution only, never commercially released. The kind of sinister European score cue a dark Southern producer would loop until it sounds like a transmission from underneath the earth.`, art: "/art/P62.jpg" },
  { id: "P63", name: "Second Line Ghost", genre: "nola-bounce", vibe: `Early 1970s New Orleans brass band field recording, warm analog tape with natural outdoor ambience and heavy room bleed. A sousaphone carrying a deep melodic bass line in G Mixolydian — round, warm, each note pitched and rhythmically active, the tuba functioning as walking bass and melody simultaneously. Brass section — four trumpets and two trombones — playing tight arranged stabs in call-and-response, punchy and bright. Solo trumpet breaking into a blues-inflected improvised passage with wide vibrato and bent notes. Congas and tambourine providing a second-line parade rhythmic feel. Mid-section: the full brass drops to silence and the sousaphone walks alone — a deep two-bar figure with the swagger of a funeral procession turning joyful. Tempo 96–106 BPM. No vocals. Recorded at a neighborhood parade, pressed on a local New Orleans label, 200 copies. The kind of brass band recording a bounce producer would chop and let the second line ride all night.`, art: "/art/P63.jpg" },
  { id: "P64", name: "Dark Crystal", genre: "melodic-trap-source", vibe: `Late 2010s dark melodic recording, clean digital production with heavy reverb and wide stereo field. A plucked digital synthesizer playing a simple three-note descending phrase in C-sharp minor — short attack, fast decay, each note isolated by silence, melancholic and hypnotic. Dark analog pad sustaining underneath with subtle detuning, low-passed until it is just warmth. Crystalline music box bell entering in a higher register, doubling the melody with delicate shimmer. Solo piano playing sparse minor ninth chord voicings, each chord sustained with long reverb tails bleeding into the next. Mid-section: the plucked synth drops out and the piano plays alone — four bars of exposed chords, devastatingly simple. No vocals. C-sharp minor — numb, isolated, beautiful in its emptiness. A four-bar cycle that gains emotional weight through repetition, the kind of unreleased loop that sat in a vault folder because it was too emotionally specific to place.`, art: "/art/P64.jpg" },
  { id: "P65", name: "Phrygian Blade", genre: "drill-source", vibe: `Early 2020s dark aggressive recording, stark and minimal with dissonant tension. A harsh orchestral string stab in F-sharp Phrygian — short, violent, a full string section hitting a dissonant chord and cutting to silence. Dark sustained cello drone underneath holding a low tritone, menacing and unresolved. Distorted detuned sawtooth synthesizer entering with a fast repeating two-note pattern — abrasive, urgent, the flat-second interval creating constant unease. Sparse reversed piano notes bleeding backward into the arrangement. Mid-section: everything drops except the cello drone and a single high violin note sustaining a minor ninth above — pure tension, no release. No vocals. F-sharp Phrygian — hostile, cold, high tension. A locked four-bar pattern, the kind of dark melodic source material a producer would layer sliding bass underneath and build the most aggressive record of the year around.`, art: "/art/P65.jpg" },
  { id: "P66", name: "Saigon Reel", genre: "vietnamese-soul", vibe: `Early 1970s South Vietnamese nhạc vàng recording, warm reel-to-reel tape with heavy oxide saturation and faint print-through bleed from decades of uncontrolled storage. A female vocal in a high floating register — nasal resonance, narrow fast vibrato blooming at the ends of phrases, pentatonic melody moving in careful stepwise intervals shaped by the tonal contours of the Vietnamese language. Nylon-string guitar playing soft arpeggiated bolero patterns underneath, a clean tremolo-soaked electric guitar adding shimmering accents through metallic spring reverb. Farfisa combo organ sustaining warm chords in the middle register. Sparse upright bass holding whole notes on root and fifth. Tempo 74–80 BPM, a slow Vietnamese bolero sway — straight eighth notes with a gentle rocking lilt. A featured sáo trúc bamboo flute solo in the bridge, breathy and slightly overblown, bending between pentatonic intervals with portamento slides derived from cải lương theater tradition. Midrange-heavy mix with limited bass extension, close-miked in a small Saigon studio with audible room reflections. Pressed in a run of 500 copies on a Sóng Nhạc label 45 in 1972, the masters lost after 1975. The kind of devastatingly melancholic Vietnamese soul record a serious digger would find buried in a Ho Chi Minh City warehouse and know immediately it was built to be looped.`, art: "/art/P66.jpg" },
  { id: "VC01", name: "Soul Confession", genre: "vocal-chop", vibe: `Mid 1970s Philadelphia soul recording, heavy analog tape saturation and deep vinyl crackle throughout. A wailing female lead vocal — emotive, strained, gospel-drenched — singing a slow aching minor key melody over lush tremolo strings and warm Rhodes electric piano chords in D Dorian — searching and unresolved. Deep upright bass walking underneath. Mid-section: the strings and bass drop to silence and the voice carries alone for eight bars, completely exposed, trembling with spiritual weight, then the Rhodes returns with deeper fuller chords. Tempo 74–84 BPM, slow and weighted. Warm analog room sound with natural tape hiss. A short harmonic cycle built to repeat hypnotically. Pressed in a quantity of 300 on a small Philadelphia soul label in 1974, the B-side that got overlooked entirely. The kind of devastating soul vocal performance built to be chopped into a two-bar loop and transformed into something unrecognizable but emotionally overwhelming.`, art: "/art/VC01.jpg" },
  { id: "VC02", name: "Church Window", genre: "vocal-chop", vibe: `Late 1960s Black church recording, warm analog tape saturation and subtle vinyl surface noise. A solo female gospel voice — raw, untrained, trembling with devotion — singing a slow hymn melody in harmonic minor over a full Hammond B3 organ with Leslie speaker rotating slowly. Thick background choir harmonies rising and falling in waves behind the lead, call and response between the soloist and the congregation. Deep upright bass walking slowly underneath. Mid-section: the organ swells to full volume and the choir drops to a hum, leaving only the lead voice and the organ in a moment of pure spiritual intensity. Tempo 68–78 BPM. Recorded live in a small wooden church on a portable tape machine, never mastered. A single pressing for the church archive. The kind of sacred recording that becomes transcendent when chopped, pitched up, and placed underneath something hard.`, art: "/art/VC02.jpg" },
  { id: "VC03", name: "Midnight Plea", genre: "vocal-chop", vibe: `Early 1970s Detroit soul recording, heavy analog tape degradation and deep vinyl surface noise throughout. A male falsetto vocal — fragile, aching, straining at the edges — singing a slow devastating melody in natural minor over sparse Rhodes electric piano chords and a lush sweeping string arrangement. Upright bass holding long sustained notes underneath. Solo flute weaving between the vocal phrases, doubling the melody in a higher register. Mid-section: the strings swell to full volume and the vocal rides above them, the falsetto cracking and bending with raw emotion before the arrangement strips back to just voice and Rhodes. Tempo 72–82 BPM. Warm analog room sound with natural tape compression. Pressed on a small Detroit independent label in 1971, limited to 500 copies, never distributed outside Michigan. A short harmonic cycle designed to feel loopable. The kind of rare soul vocal performance a producer would pitch up three semitones and build entire worlds around.`, art: "/art/VC03.jpg" },
  { id: "VC04", name: "Golden Dust", genre: "vocal-chop", vibe: `Mid 1970s orchestral soul recording, warm analog tape saturation and moderate vinyl surface noise. A female vocal trio singing tight minor-key harmonies — bright, youthful, slightly breathless — over a dramatic string section and punchy horn stabs. Rhodes electric piano playing rich extended chord voicings underneath, live electric bass locked into a bouncy groove. Mid-section: the horns and strings drop to silence and the lead voice breaks away from the trio into a brief solo passage — raw, pleading, straining at the top of her range — before the full arrangement crashes back in with the harmonies stacking. Tempo 96–108 BPM, energetic and propulsive. Bright analog tape with light vinyl crackle. Pressed as the B-side of a regional 45 single in 1974, the A-side got minor local airplay but this side was overlooked entirely. Designed to be pitched up several semitones and transformed into a buoyant chipmunked sample flip.`, art: "/art/VC04.jpg" },
];

